CREATE TABLE bank_construction_cases(project_id uuid PRIMARY KEY REFERENCES house_projects(id),case_id uuid NOT NULL UNIQUE,owner_id uuid NOT NULL REFERENCES accounts(id),idempotency_key uuid NOT NULL,approval_status varchar(20) NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE bank_stage_submissions (
 id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES house_projects(id),stage_id uuid NOT NULL REFERENCES construction_stages(id),actor_id uuid NOT NULL REFERENCES accounts(id),acceptance_id uuid NOT NULL REFERENCES acceptance_submissions(id),revision integer NOT NULL CHECK(revision>0),previous_id uuid REFERENCES bank_stage_submissions(id),
 state varchar(24) NOT NULL CHECK(state IN ('PENDING','UNKNOWN','RECEIVED','ACCEPTED','NEEDS_INFORMATION')),version bigint NOT NULL DEFAULT 0 CHECK(version>=0),idempotency_key uuid NOT NULL,request_hash varchar(64) NOT NULL,bank_key uuid NOT NULL UNIQUE,packet jsonb NOT NULL,bank_reference varchar(100),reason varchar(1000),attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0),auto_attempts integer NOT NULL DEFAULT 0 CHECK(auto_attempts>=0),lease_token uuid,lease_until timestamptz,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,
 UNIQUE(stage_id,revision),UNIQUE(actor_id,project_id,idempotency_key),CHECK((lease_token IS NULL)=(lease_until IS NULL))
);
CREATE INDEX bank_stage_pending_idx ON bank_stage_submissions(created_at) WHERE state IN ('PENDING','UNKNOWN','RECEIVED');
CREATE TABLE bank_stage_attempts(id uuid PRIMARY KEY,submission_id uuid NOT NULL REFERENCES bank_stage_submissions(id),attempt_number integer NOT NULL CHECK(attempt_number>0),outcome varchar(24) NOT NULL,created_at timestamptz NOT NULL,UNIQUE(submission_id,attempt_number));
CREATE TABLE bank_mock_stage_receipts(id uuid PRIMARY KEY,payload_hash varchar(64) NOT NULL,state varchar(24) NOT NULL CHECK(state IN ('RECEIVED','ACCEPTED','NEEDS_INFORMATION')),target_state varchar(24) NOT NULL CHECK(target_state IN ('ACCEPTED','NEEDS_INFORMATION')),reason varchar(1000),received_at timestamptz NOT NULL);
